import { execFileSync } from 'node:child_process'
import { writeFileSync } from 'node:fs'
const queries={
  "SCHEMA": "SELECT m.name AS table_name, group_concat(p.name || ':' || p.type,' | ') AS columns FROM sqlite_master m,pragma_table_info(m.name) p WHERE m.type='table' AND (m.name IN ('inventory_stock','inventory_reservations','inventory_movements','inventory_stock_checks','inventory_operations','inventory_operation_evidence','inventory_stocktake_sessions','inventory_stocktake_items','catalog_variants','catalog_products','catalog_stock_positions','orders','order_items','catalog_stock_reconciliation_journal','catalog_stock_reconciliation_validations','inventory_v2_baseline_stock') OR m.name LIKE '%reserv%' OR m.name LIKE '%reconcil%' OR m.name LIKE '%merge%' OR m.name LIKE '%stocktake%') GROUP BY m.name ORDER BY m.name",
  "STOCK_MODEL": "SELECT 'stock' AS what,inventory_source AS source,COUNT(*) AS records,COUNT(DISTINCT variant_id) AS skus,SUM(quantity) AS physical,SUM(reserved_quantity) AS cached_reserved,SUM(CASE WHEN quantity<=0 AND reserved_quantity>0 THEN 1 ELSE 0 END) AS zero_or_negative_cached_reserved FROM inventory_stock GROUP BY inventory_source UNION ALL SELECT 'reservation',inventory_source,COUNT(*),COUNT(DISTINCT variant_id),NULL,SUM(quantity),SUM(CASE WHEN status='active' THEN 1 ELSE 0 END) FROM inventory_reservations GROUP BY inventory_source ORDER BY what,source",
  "ALL_RESERVATION_EXPOSURES_SUMMARY": "WITH res AS (\n  SELECT r.inventory_source AS src,r.variant_id AS vid,\n    COUNT(*) AS reservation_rows,SUM(r.quantity) AS active_res,\n    SUM(CASE WHEN o.order_date>='2026-10-01' THEN r.quantity ELSE 0 END) AS res_oct,\n    SUM(CASE WHEN o.order_date>='2026-09-19' THEN r.quantity ELSE 0 END) AS res_30d,\n    SUM(CASE WHEN o.order_date>='2026-09-01' THEN r.quantity ELSE 0 END) AS res_sept,\n    SUM(CASE WHEN o.order_date>='2026-10-01' THEN 1 ELSE 0 END) AS recent_order_rows,\n    SUM(CASE WHEN o.id IS NULL OR COALESCE(o.shipping_status,'not_sent')='sent'\n        OR COALESCE(o.order_status,'active') IN ('deleted','archived') OR COALESCE(o.archived_at,'')<>'' THEN r.quantity ELSE 0 END) AS invalid_active_res,\n    MIN(o.order_date) AS oldest_order,MAX(o.order_date) AS newest_order,\n    MIN(r.created_at) AS oldest_res_created,MAX(r.created_at) AS latest_res_created\n  FROM inventory_reservations r LEFT JOIN orders o ON o.id=r.order_id\n  WHERE r.status='active' AND r.variant_id IS NOT NULL\n  GROUP BY r.inventory_source,r.variant_id\n), stock AS (\n  SELECT inventory_source AS src,variant_id AS vid,COUNT(*) AS stock_rows,\n    SUM(quantity) AS physical,SUM(reserved_quantity) AS cached_res,\n    MIN(id) AS first_stock_id,\n    MAX(updated_at) AS last_stock_update\n  FROM inventory_stock WHERE variant_id IS NOT NULL\n  GROUP BY inventory_source,variant_id\n), joined AS (\n SELECT res.*,COALESCE(stock.physical,0) AS physical,COALESCE(stock.cached_res,0) AS cached_res,\n  COALESCE(stock.stock_rows,0) AS stock_rows,stock.first_stock_id,stock.last_stock_update,\n  p.name AS product_name, v.color, v.material, v.length, v.gender, v.size_label AS size,\n  v.category, v.is_active AS sku_active,p.is_active AS product_active,\n  COALESCE(stock.physical,0)-res.active_res AS available\n FROM res LEFT JOIN stock ON stock.src=res.src AND stock.vid=res.vid\n LEFT JOIN catalog_variants v ON v.id=res.vid\n LEFT JOIN catalog_products p ON p.id=v.product_id\n) SELECT src,COUNT(*) AS skus_with_active_res,SUM(active_res) AS total_active_res,SUM(CASE WHEN physical<=0 THEN 1 ELSE 0 END) AS physical_le_zero_skus,SUM(CASE WHEN physical<=0 AND recent_order_rows>0 THEN 1 ELSE 0 END) AS physical_le_zero_with_oct_orders,SUM(CASE WHEN physical<active_res THEN 1 ELSE 0 END) AS physical_below_reserved_skus,SUM(CASE WHEN physical>0 AND physical<active_res THEN 1 ELSE 0 END) AS positive_but_short_skus,SUM(CASE WHEN cached_res<>active_res THEN 1 ELSE 0 END) AS cached_reserve_mismatch,SUM(CASE WHEN stock_rows=0 THEN 1 ELSE 0 END) AS missing_stock_row_skus,SUM(CASE WHEN invalid_active_res>0 THEN 1 ELSE 0 END) AS stale_active_reserve_skus FROM joined GROUP BY src",
  "ALL_PHYSICAL_ZERO_NEGATIVE_WITH_RESERVES": "WITH res AS (\n  SELECT r.inventory_source AS src,r.variant_id AS vid,\n    COUNT(*) AS reservation_rows,SUM(r.quantity) AS active_res,\n    SUM(CASE WHEN o.order_date>='2026-10-01' THEN r.quantity ELSE 0 END) AS res_oct,\n    SUM(CASE WHEN o.order_date>='2026-09-19' THEN r.quantity ELSE 0 END) AS res_30d,\n    SUM(CASE WHEN o.order_date>='2026-09-01' THEN r.quantity ELSE 0 END) AS res_sept,\n    SUM(CASE WHEN o.order_date>='2026-10-01' THEN 1 ELSE 0 END) AS recent_order_rows,\n    SUM(CASE WHEN o.id IS NULL OR COALESCE(o.shipping_status,'not_sent')='sent'\n        OR COALESCE(o.order_status,'active') IN ('deleted','archived') OR COALESCE(o.archived_at,'')<>'' THEN r.quantity ELSE 0 END) AS invalid_active_res,\n    MIN(o.order_date) AS oldest_order,MAX(o.order_date) AS newest_order,\n    MIN(r.created_at) AS oldest_res_created,MAX(r.created_at) AS latest_res_created\n  FROM inventory_reservations r LEFT JOIN orders o ON o.id=r.order_id\n  WHERE r.status='active' AND r.variant_id IS NOT NULL\n  GROUP BY r.inventory_source,r.variant_id\n), stock AS (\n  SELECT inventory_source AS src,variant_id AS vid,COUNT(*) AS stock_rows,\n    SUM(quantity) AS physical,SUM(reserved_quantity) AS cached_res,\n    MIN(id) AS first_stock_id,\n    MAX(updated_at) AS last_stock_update\n  FROM inventory_stock WHERE variant_id IS NOT NULL\n  GROUP BY inventory_source,variant_id\n), joined AS (\n SELECT res.*,COALESCE(stock.physical,0) AS physical,COALESCE(stock.cached_res,0) AS cached_res,\n  COALESCE(stock.stock_rows,0) AS stock_rows,stock.first_stock_id,stock.last_stock_update,\n  p.name AS product_name, v.color, v.material, v.length, v.gender, v.size_label AS size,\n  v.category, v.is_active AS sku_active,p.is_active AS product_active,\n  COALESCE(stock.physical,0)-res.active_res AS available\n FROM res LEFT JOIN stock ON stock.src=res.src AND stock.vid=res.vid\n LEFT JOIN catalog_variants v ON v.id=res.vid\n LEFT JOIN catalog_products p ON p.id=v.product_id\n) SELECT src,vid,product_name,color,material,length,gender,size,category,sku_active,physical,active_res,cached_res,available,stock_rows,reservation_rows,res_oct,res_30d,invalid_active_res,oldest_order,newest_order,last_stock_update FROM joined WHERE physical<=0 ORDER BY CASE WHEN res_oct>0 THEN 0 ELSE 1 END,src,physical,active_res DESC,vid LIMIT 1500",
  "POSITIVE_BUT_SHORT_OR_COUNTER_MISMATCH": "WITH res AS (\n  SELECT r.inventory_source AS src,r.variant_id AS vid,\n    COUNT(*) AS reservation_rows,SUM(r.quantity) AS active_res,\n    SUM(CASE WHEN o.order_date>='2026-10-01' THEN r.quantity ELSE 0 END) AS res_oct,\n    SUM(CASE WHEN o.order_date>='2026-09-19' THEN r.quantity ELSE 0 END) AS res_30d,\n    SUM(CASE WHEN o.order_date>='2026-09-01' THEN r.quantity ELSE 0 END) AS res_sept,\n    SUM(CASE WHEN o.order_date>='2026-10-01' THEN 1 ELSE 0 END) AS recent_order_rows,\n    SUM(CASE WHEN o.id IS NULL OR COALESCE(o.shipping_status,'not_sent')='sent'\n        OR COALESCE(o.order_status,'active') IN ('deleted','archived') OR COALESCE(o.archived_at,'')<>'' THEN r.quantity ELSE 0 END) AS invalid_active_res,\n    MIN(o.order_date) AS oldest_order,MAX(o.order_date) AS newest_order,\n    MIN(r.created_at) AS oldest_res_created,MAX(r.created_at) AS latest_res_created\n  FROM inventory_reservations r LEFT JOIN orders o ON o.id=r.order_id\n  WHERE r.status='active' AND r.variant_id IS NOT NULL\n  GROUP BY r.inventory_source,r.variant_id\n), stock AS (\n  SELECT inventory_source AS src,variant_id AS vid,COUNT(*) AS stock_rows,\n    SUM(quantity) AS physical,SUM(reserved_quantity) AS cached_res,\n    MIN(id) AS first_stock_id,\n    MAX(updated_at) AS last_stock_update\n  FROM inventory_stock WHERE variant_id IS NOT NULL\n  GROUP BY inventory_source,variant_id\n), joined AS (\n SELECT res.*,COALESCE(stock.physical,0) AS physical,COALESCE(stock.cached_res,0) AS cached_res,\n  COALESCE(stock.stock_rows,0) AS stock_rows,stock.first_stock_id,stock.last_stock_update,\n  p.name AS product_name, v.color, v.material, v.length, v.gender, v.size_label AS size,\n  v.category, v.is_active AS sku_active,p.is_active AS product_active,\n  COALESCE(stock.physical,0)-res.active_res AS available\n FROM res LEFT JOIN stock ON stock.src=res.src AND stock.vid=res.vid\n LEFT JOIN catalog_variants v ON v.id=res.vid\n LEFT JOIN catalog_products p ON p.id=v.product_id\n) SELECT src,vid,product_name,color,material,length,gender,size,physical,active_res,cached_res,available,res_oct,newest_order,invalid_active_res FROM joined WHERE (physical>0 AND physical<active_res) OR cached_res<>active_res ORDER BY CASE WHEN res_oct>0 THEN 0 ELSE 1 END,physical-active_res,src,vid LIMIT 1000",
  "NEGATIVE_PHYSICAL_GLOBAL": "SELECT s.inventory_source AS src,s.variant_id AS vid,p.name AS product_name,v.color,v.size_label AS size,s.quantity,s.reserved_quantity,s.updated_at FROM inventory_stock s LEFT JOIN catalog_variants v ON v.id=s.variant_id LEFT JOIN catalog_products p ON p.id=v.product_id WHERE s.quantity<0 ORDER BY s.inventory_source,s.quantity,s.id LIMIT 200",
  "HISTORY_TABLE_INDEX": "SELECT name AS table_name FROM sqlite_master WHERE type='table' AND (name LIKE '%movement%' OR name LIKE '%stock%' OR name LIKE '%reservation%' OR name LIKE '%reconcil%' OR name LIKE '%variant%' OR name LIKE '%revision%' OR name LIKE '%merge%' OR name LIKE '%arrival%' OR name LIKE '%audit%' OR name LIKE '%transfer%') ORDER BY name"
};
const run = (sql) => {
  const stmt=sql.trim().toUpperCase();
  if(!/^(SELECT|WITH)\b/.test(stmt)||/\b(UPDATE|DELETE|INSERT|ALTER|DROP|CREATE|REPLACE|PRAGMA|ATTACH|DETACH|VACUUM)\b/.test(stmt))throw Error('Read-only query gate rejected');
  const raw=execFileSync('npx',['wrangler','d1','execute','orders_db_prod','--remote','--config','wrangler.jsonc','--command',sql.trim(),'--json'],{encoding:'utf8',maxBuffer:16*1024*1024,timeout:120000});
  const parsed=JSON.parse(raw);
  if(parsed.some(x=>x.success!==true))throw Error('D1 SELECT failed');
  return parsed.flatMap(x=>x.results||[]);
};
const report={};
for(const [label,sql] of Object.entries(queries)){
 const rows=run(sql);
 report[label]=rows;
 console.log('== '+label+' == '+JSON.stringify(rows));
}
writeFileSync('stock-forensic-phase1.json',JSON.stringify(report,null,2));
console.log('FORENSIC_PHASE1_READ_ONLY_COMPLETE');